import { setupWorker } from "msw/browser";
import { handlers } from "./handlers";

/**
 * Browser worker for dev mode. Start it by setting NEXT_PUBLIC_MSW=1 before
 * `npm run dev`. The service worker script (public/mockServiceWorker.js) is
 * generated by `npm run msw:init`.
 */
export const worker = setupWorker(...handlers);

export async function enableMocking(): Promise<void> {
  if (process.env.NEXT_PUBLIC_MSW !== "1") return;
  await worker.start({ onUnhandledRequest: "bypass" });
}
